#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DType {
    /// Category: "i" (integer), "f" (float), "b" (bool)
    pub kind: char,
    /// Element size in bytes
    pub itemsize: usize,
    /// Alignment in bytes (must be > 0 and <= itemsize)
    pub alignment: usize,
    /// Non-empty name (typically the same as the spec)
    pub name: String,
    /// Signedness for integer types; false for float/bool
    pub signed: bool,
}

pub fn numpy_dtype(type_spec: &str) -> DType {
    match type_spec {
        "int8" => DType {
            kind: 'i',
            itemsize: 1,
            alignment: 1,
            name: "int8".to_string(),
            signed: true,
        },
        "int16" => DType {
            kind: 'i',
            itemsize: 2,
            alignment: 2,
            name: "int16".to_string(),
            signed: true,
        },
        "int32" => DType {
            kind: 'i',
            itemsize: 4,
            alignment: 4,
            name: "int32".to_string(),
            signed: true,
        },
        "int64" => DType {
            kind: 'i',
            itemsize: 8,
            alignment: 8,
            name: "int64".to_string(),
            signed: true,
        },
        "float32" => DType {
            kind: 'f',
            itemsize: 4,
            alignment: 4,
            name: "float32".to_string(),
            signed: false,
        },
        "float64" => DType {
            kind: 'f',
            itemsize: 8,
            alignment: 8,
            name: "float64".to_string(),
            signed: false,
        },
        "bool" => DType {
            kind: 'b',
            itemsize: 1,
            alignment: 1,
            name: "bool".to_string(),
            signed: false,
        },
        _ => panic!("unsupported dtype spec: {type_spec}"),
    }
}